def script_hash(script_text: str) -> str:
    """Return the CSP source expression (``'sha256-...'``) for an inline script's exact text."""
    digest = hashlib.sha256(script_text.encode("utf-8")).digest()
    return "'sha256-" + base64.b64encode(digest).decode("ascii") + "'"


def build_html(*, title: str, css: str, js: str, data_json: str) -> str:
    """Return the complete HTML document.

    Args:
        title: Plain-text page title (escaped here).
        css: Stylesheet text.
        js: Page script text (must not contain ``</script``).
        data_json: JSON payload already made safe for a script element
            (``<``, ``>``, ``&`` and line separators escaped).
    """
    script_text = f"\n{js}\n"
    csp = (
        "default-src 'none'; style-src 'unsafe-inline'; "
        f"script-src {script_hash(script_text)}; img-src data:; base-uri 'none'; form-action 'none'"
    )
    return (
        "<!doctype html>\n"
        '<html lang="en">\n<head>\n'
        '<meta charset="utf-8">\n'
        '<meta name="viewport" content="width=device-width, initial-scale=1">\n'
        f'<meta http-equiv="Content-Security-Policy" content="{_html_lib.escape(csp)}">\n'
        f"<title>{_html_lib.escape(title)}</title>\n"
        f"<style>\n{css}\n</style>\n"
        "</head>\n<body>\n"
        f"{_BODY}\n"
        f'<script type="application/json" id="eval-data">{data_json}</script>\n'
        f"<script>{script_text}</script>\n"
        "</body>\n</html>\n"
    )
